interface Student {
    id: number,
    name: string,
    age: number,
    sex: string,
    photo: string
}

function Person() {
    return (
        <div className="student">
            <div className="avatar"></div>
            <h1>张三</h1>
            <h2>编号</h2>
            <p>性别：男 年龄：27</p>
        </div>
    )
}

export default Person;
